```c
#include <stdio.h>

#include <string.h>

int main(void)
{
char data[] = " C is\t too#much\nfun!";

const char tokseps[] = " \t\n#";/* 分隔符 */
char * pt;

puts(data);

pt = strtok(data,tokseps);      /* 首次调用 */
while (pt)                          /* 如果pt是NULL, 则退出 */
{
puts (pt);                      /* 显示记号 */
pt = strtok(NULL, tokseps);/* 下一个记号 */
}
return 0;
}

下面是该示例的输出:
C is too#much
fun!
